INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Acus Acuta', 'migrated/Hechizos_de_Sanacion__Acus+Acuta.png', 'Invoca una &#34;aguja&#34; azul que funciona de la misma manera que una convencional, generando un pequeño ducto que atraviesa la piel o músculos sin causar ningún tipo de dolor al pinchar. Puede utilizarse tanto para inyectar como para sacar sangre, conectando el ducto mágico con un emisor/receptor de fluidos. Creación <a href="https://www.hogwartsrol.com/t93416-camara-de-la-creacion-magica-acus-acuta-derek-lillie">Aquí</a>', '180', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
