INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Braquiaemendo', 'migrated/Hechizos_de_Sanacion__Braquiaemendo.png', 'Repara huesos rotos, realizado de forma incorrecta el hueso desaparece, se utiliza por lo general después de <i>Ferula</i>.', '110', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Camillaris Incanto', 'migrated/Hechizos_de_Sanacion__Camillaris+Incanto.jpg', 'Genera Camillas. Son flotantes y vienen en planchas mágicas expandibles. Para su fácil transporte vienen miniaturizadas como las muletas, para expandirlas se deben de agitar. Pueden transportarse con el médico si usa transformación junto con el herido, vienen hechizadas para flotar.', '90', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Celum Praesidium', 'migrated/Hechizos_de_Sanacion__Celum+Praesidium.png', 'Con un movimiento circular en el aire, este hechizo crea ondas que detectan toxinas dañinas en un rango de 50 metros a la redonda, las elimina y purifica el aire para evitar su transmisión. Tiene una duración de hasta 30 minutos. Creación <a href="https://www.hogwartsrol.com/t77375p10-creacion-magica-celum-praesidium-julieta-alphonse#417142">Aquí</a>', '150', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Corporalis Sanitatis', 'migrated/Hechizos_de_Sanacion__Corporalis+Sanitatis.png', 'Este hechizo permite tener un registro del estado de la sangre del objetivo lo que puede llegar a determinar todos los valores básicos de un hemograma completo.', '150', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Corpus Intra', 'migrated/Hechizos_de_Sanacion__Corpus+Intra.png', 'Lo más cercano que tienes para ver adentro del cuerpo humano que sigue vivo, este hechizo genera una pantalla area que muestra en detalle como se ve a quien apuntas por dentro, con movimientos delicados de muñeca con tu varita puedes llegar a entrar en capas profundas como dentro de huesos, tendones y venas. Es el reemplazo mágico de la ecografía, la resonancia y los rayos x.', '300', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Crocio Incantato', 'migrated/Hechizos_de_Sanacion__Crocio+Incantato.jpg', 'Primeros Auxilios.', '90', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
