INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Electricae Inpulsa', 'migrated/Hechizos_de_Sanacion__Electricae+Inpulsa.png', 'Un hechizo que lanza un pequeño choque eléctrico al corazón, es de uso médico para hacer reanimación cardiopulmonar.', '80', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
