INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Episkey', 'migrated/Hechizos_de_Sanacion__Episkey.png', 'Para componer pequeñas fracturas menores de manera rápida y eficaz. Pero su uso sin experiencia podría provocar la desaparición de un hueso o algún componente óseo.', '120', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Febris Imperium', 'migrated/Hechizos_de_Sanacion__Febris+Imperium.png', 'Regula gradualmente la temperatura corporal en estados febriles. Es un hechizo acumulativo, se debe efectuar una vez cada hora durante cuatro horas para que sea efectivo. Creación <a href="https://www.hogwartsrol.com/t68150-creacion-magica-febris-imperium-atwood-olivia">aquí</a>', '200', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Ferula', 'migrated/Hechizos_de_Sanacion__Ferula.jpg', 'Sirve para entablillar al herido en caso de que se haya roto un hueso.', '120', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Fractio', 'migrated/Hechizos_de_Sanacion__Fractio.png', 'Hechizo que cura o restablece huesos malformados o aquellos afectados por diversas enfermedades, fracturándolos de forma seca e indolora. Se ha de utilizar en conjunto con otros hechizos de sanación para culminar el proceso con éxito. Creación <a href="https://www.hogwartsrol.com/t72663-creacion-magica-fractio-giffard-logan">aqui</a>', '200', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Hemo Dialium', 'migrated/Hechizos_de_Sanacion__Hemo+Dialium.png', 'Se trata de un hechizo que elimina las toxinas de la sangre cuando un órgano está fallando (como el riñón o el hígado). Sirve también para purificarla en caso de intoxicación severa. Es un hechizo acumulativo, se debe recitar una vez cada hora durante cuatro horas para que la sangre sea filtrada total y eficazmente. No cura la causa de la intoxicación, tan sólo filtra la sangre. Creación <a href="https://www.hogwartsrol.com/t23860-creacion-magica-isolda-carrow-emett-blacwood">aquí</a>', '200', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Kemaio', 'migrated/Hechizos_de_Sanacion__Kemaio.jpg', 'Produce Alcohol Etílico, de color rojo fuerte, que sirve para desinfectar la herida.', '90', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Latidum Sonorus', 'migrated/Hechizos_de_Sanacion__Latidum+Sonorus.png', 'La varita debe apuntar al órgano que se quiere escuchar, ocasionando que funcione como un amplificador, pudiendo identificar el sonido del latido del corazón, el sonido de los pulmones o bien, del estómago o intestinos.  Creación <a href="https://www.hogwartsrol.com/t60394-creacion-magica-latidum-sonorus-lillie-jonathan">aquí</a>', '150', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Mulamontoletus', 'migrated/Hechizos_de_Sanacion__Mulamontoletus.jpg', 'Genera Muletas. Éstas vienen como pequeños bastones de madera, los cuales agitándolos se expanden y pasan a tomar la forma de las muletas normales, están encantadas para hacer que se muevan por el mago.', '100', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Oculi Refectionem', 'migrated/Hechizos_de_Sanacion__Oculi+Refectionem.jpg', 'Reconstruye la cuenca ocular completamente y el globo ocular cuando este presenta daños. el hechizo solo sirve para reconstruir un solo ojo por hechizo, además requiere de drenado mágico constante mientras se realiza. Hechizo efectivo 100% al final del proceso, pero con efectos secundarios. Creación <a href="https://www.hogwartsrol.com/t31835-creacion-magica-oculi-refectionem-ekaterina-romanova-y-byron-rosier">aquí</a>', '250', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Oculus', 'migrated/Hechizos_de_Sanacion__Oculus.png', 'Genera lentes con el aumento que el mago necesite. Con solo tocarlo con la varita, el médico puede aumentar o reducir su aumento, logrando incluso a tener la posibilidad que el mago vea los glóbulos rojos de la sangre y la mas diminuta partícula de polvo de una herida.', '100', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Practo Incantato', 'migrated/Hechizos_de_Sanacion__Practo+Incantato.jpg', 'Se utiliza para colocar los huesos en la posición adecuada para después soldarlos', '200', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Puer Visibilis', 'migrated/Hechizos_de_Sanacion__Puer+Visibilis.png', 'El hechizo podrá realizar copias exactas, de una parte del cuerpo humano. Dichas copias podrán ser guardadas para su uso sin que el paciente esté presente. Creación <a href="https://www.hogwartsrol.com/t22962-creacion-magica-elya-campbell-william-ellis">aquí</a>', '350', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Remolotum', 'migrated/Hechizos_de_Sanacion__Remolotum.png', 'Extrae elementos contundentes que se encuentran en el interior de la herida como suciedad o partículas de vidrio grandes. Generalmente se utiliza luego del Kemaio.', '150', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Reparo Psychica', 'migrated/Hechizos_de_Sanacion__.png', 'Hechizo que repara temporalmente las fracturas de la psique del individuo gracias a pequeñas ondas, restaurando la integridad mental y emocional dañada por sentimientos negativos (On rol)', '', '0', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Repeciare', 'migrated/Hechizos_de_Sanacion__Repeciare.png', 'Hechizo para reconstruir y darle forma a tejidos estructurales blandos (piel, músculos, tendones, la grasa, los vasos sanguíneos, los nervios, etc.). No sirve para órganos, ni huesos. Se usa en conjunto con las pociones pertinentes. Creación <a href="https://www.hogwartsrol.com/t49981p10-creacion-magica-repeciare-scorpius-william">aquí</a>', '200', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Revisus Arterius', 'migrated/Hechizos_de_Sanacion__Revisus+Arterius.png', 'Permite aparecer ante los ojos del mago un mapa detallado de cada vena, arteria y vasos sanguíneos del cuerpo de la persona a examinar, otorgando además la capacidad de detectar trombos y obstrucciones dentro del sistema circulatorio. Creación <a href="https://www.hogwartsrol.com/t39643-creacion-magica-revisus-arterius-william-morgan">aquí</a>', '200', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Thermometrum', 'migrated/Hechizos_de_Sanacion__Thermometrum.png', 'Este hechizo permite saber la temperatura corporal de una persona. (A tener en cuenta que un licántropo suele tener valores más elevados que la media y los vampiros menores a la misma).', '50', '999', '0', '0', '0', '0', '0', '0', '0', '0', '22', '1', '0');
