INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Expecto Patronum', 'migrated/Hechizos_de_Defensa__Expecto+Patronum.png', 'Este antiguo y difícil encantamiento materializa los pensamientos felices en un guardián mágico que puede proteger contra la magia más oscura. Puede usarse para repeler dementores y lethifolds, y también para enviar mensajes a otras personas.', '300', '999', '0', '0', '0', '0', '0', '0', '0', '0', '24', '1', '0');
