INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Flumen Florum', 'migrated/Hechizos_de_Defensa__Flumen+Florum.png', 'Aparece una flor gigante(a elección) sin tallo frente al lanzador cuya gran corola absorbe el ataque enemigo. En caso de ser una defensa exitosa, la flor desaparece volviéndose cientos de pequeños pétalos. Creación <a href="https://www.hogwartsrol.com/t76410-creacion-magica-flumem-florum-magnus-morgan">aquí</a>', '250', '999', '0', '0', '0', '0', '0', '0', '0', '0', '24', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Foggeo', 'migrated/Hechizos_de_Defensa__Foggeo.png', 'Hechizo que provoca una nube de niebla mágica que paraliza y devora en su interior la magia de hechizos de elementos impidiendo que el ataque llegue a su destino. Es una niebla  inofensiva que no afecta a los magos y cuyo alcance máximo son tres o cuatro metros desde el lugar de lanzamiento, la cual desaparecer tras un turno. Creación <a href="https://www.hogwartsrol.com/t70207-creacion-magica-foggeo-giffard-chuck">aquí</a>', '180', '999', '0', '0', '0', '0', '0', '0', '0', '0', '24', '1', '0');
INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Galaxia Explosio', 'migrated/Hechizos_de_Defensa__Galaxia+Explosio.png', 'Crea una pequeña corriente de energía de colores que gira como si fuese una galaxia la cual se posiciona entre el hechizo y el conjurador absorbiendo el ataque, explotando en polvo de estrellas después. Creación <a href="https://www.hogwartsrol.com/t80644-creacion-magica-galaxia-explosio-whilemina-morgan">aquí</a>', '350', '999', '0', '0', '0', '0', '0', '0', '0', '0', '24', '1', '0');
