INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Glacies Iaculat', 'migrated/Hechizos_de_Ataque_y_Defensa__Glacies+Iaculat.jpg', 'La varita con el agua del ambiente, forma pequeñas esferas de hielo del tamaño de un balín o un poco más grandes para ser lanzadas con fuerza al contrincante, similar a las pistolas de aire con balines ó gotcha. Creación <a href="https://www.hogwartsrol.com/t35150-creacion-magica-glacies-iaculat-seo-taeyeon-ganimedes-windhunter">aquí</a>', '160', '999', '0', '0', '0', '0', '0', '0', '0', '0', '25', '1', '0');
