INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Lumos Solem', 'migrated/Hechizos_de_Ataque_y_Defensa__Lumos+Solem.png', 'Hechizo que produce un potente rayo de luz solar que se puede usar para dañar al oponente para cegarlo durante unos segundos si se conjura con fuerza, también se usa como contrahechizo para otros ataques producidos por plantas o liberar a aquellos que se encuentren bajo los efectos de hechizos conformados por ausencia de luz. Creación <a href="https://www.hogwartsrol.com/t40303-creacion-magica-lumos-solem-lancelot-olivia">aquí</a>', '200', '999', '0', '0', '0', '0', '0', '0', '0', '0', '25', '1', '0');
