INSERT INTO `smf_stshop_items` (`name`, `image`, `description`, `price`, `stock`, `module`, `info1`, `info2`, `info3`, `info4`, `input_needed`, `can_use_item`, `delete_after_use`, `catid`, `status`, `itemlimit`) VALUES ('Sphinx Praesidium', 'migrated/Hechizos_de_Ataque_y_Defensa__Sphinx+Praesidium.png', 'Crea una esfinge de arena que protege al invocador poniéndose delante de él y rugiendo levantando una pequeña tormenta de arena que bloquea los hechizos. En modo ofensivo, ataca al oponente usando sus garras de arena para aprisionar a su oponente contra el suelo antes de estallar en una explosión de arena. Creación <a href="https://www.hogwartsrol.com/t102414-camara-de-la-creacion-magica-sphinx-praesidium-cheryl-willow">aquí</a>', '300', '999', '0', '0', '0', '0', '0', '0', '0', '0', '25', '1', '0');
